%let file = top50_concise.csv;
*this file contains hand-collected clinical trials from the top 50 industry sponsors 
(searched and downloaded from ClinicalTrials.gov);

%let output_sas = top50_drug_trials;


proc import 
	out= temp 
	datafile = "&folder.\&file"
	DBMS=csv  REPLACE;
	guessingrows=1000;

/*** dates are in text format -- change it in excel [just select and choose "short date", and choose
the format like Jan 1, 2018] ***
for obs that only have month-year, I assume the date is 15th of the month) ***/

data final;
	set drug;
	*if Funded_Bys="Industry"; *drop Funded_Bys; *92.92% of obs;
	if find(Funded_Bys,'Industry','i')>0;
	if find(Funded_Bys,'NIH','i')>0 or find(Funded_Bys,'U.S. Fed','i')>0 then govfund = 1; else govfund=0;

run;

	merge "condition" from ClinicalTrials.gov (disease treated in a trial) with MeSH (disease category) information.

	downloded MESH dictionary from https://www.nlm.nih.gov/mesh/meshhome.html, saved as "MeSH_C_F_diseases.xlsx"

	output: trial level, with condition (therapeutic area) info

/*************************************************************************************************************/
/*************************************************************************************************************/


libname ct "&folder.";

%let input_ct = top50_drug_trials; *from PART 1;
%let input_mesh = MeSH_C_F_diseases; *downloaded from "https://www.nlm.nih.gov/mesh/meshhome.html";

%let output = top50_drug_trials_addmkt; 

proc import 
	out= mesh 
	datafile = "&folder.\&input_mesh..xlsx"
	DBMS=xlsx  replace;
	GETNAMES=YES;

proc expand data=agg5 out=agg6 method = none; 
  by firm mesh_class3;
  id year; 

	convert inip2=inip2_movsum3        / transformout= (MOVSUM 3 );
	convert inip3=inip3_movsum3        / transformout= (MOVSUM 3 );
run;

proc sql;
	create table final as
	select *, count(distinct(NCT_number)) as n_byfirm
	from  final4
	group by firm;
quit;

proc freq;
	table n_byfirm;
run;

data final;
	set final;
	if n_byfirm>100;
run;

proc freq order=freq;
	table firm  rgst_yr;
run;

data ct.&output_sas;
	set final;
run;

run;

proc contents data=final3 varnum;
run;

data final3;
	set final2;

*convert character to date format (default: 1st day of the month);
*if date is not given, use 15th day in that month;
Start_dt = input( Start_Date , ANYDTDTE30.); 
	if Start_Date_real ne 1 then Start_dt = mdy(month(Start_dt), 15, year(Start_dt));
complt_dt = input( complt_date , ANYDTDTE30.); 
	if complt_date_real ne 1 then complt_dt = mdy(month(complt_dt), 15, year(complt_dt));

rgst_submit_dt = input( First_Submitted , ANYDTDTE30.); 
rgst_post_dt = input( First_posted , ANYDTDTE30.); 

result_submit_dt = input ( Results_First_Submitted , ANYDTDTE30.); 
result_post_dt = input ( Results_First_posted , ANYDTDTE30.); 

format Start_dt--result_post_dt MMDDYY10.;

	*year;
	start_yr = year(Start_dt);
	rgst_yr = year(rgst_post_dt);

	drop Start_Date complt_date First_Submitted First_posted   rgst_submit_dt result_submit_dt 
Primary_Completion_Date Completion_Date Last_Update_Posted Results_First_Submitted Results_First_posted;

run;

data final;
	length mesh_class1 $ 10;
	length mesh_class2 $ 20;
	length mesh_class3 $ 30;
	set raw2;
	drop mesh_1--mesh_10 cond;
run;

data ct.&output;	
	set final;
run;
*clinical trial level data, with MeSH classification included;

data temp2;
	set ct.&input;

	if  rgst_yr <= start_yr + 2;*exclude older trials registered ex-post ;

	if complt_dt>Start_dt then complt_yr = year(complt_dt);
	if rgst_yr > complt_yr and missing(complt_yr) = 0 then complt_yr=rgst_yr;

	*to facilitate summing in proc sql;
	if phase = 1 then p1 = NCT_Number;
		else if phase = 2 then p2 = NCT_Number;
		else if phase = 3 then p3 = NCT_Number;
run;

proc freq data=temp2;
	table check;
run;

data mkt_firm0;
	set mkt_firm;

		do y = 2005 to 2018;
		year = y;
		output;
		end; 
		drop y;
run;

/*** save permanently -- firm-market-year level data *******/

data ct.&output;
	set temp2;
run;


PROC EXPORT DATA=temp2
            OUTFILE="&folder.\&output..dta"
            DBMS=STATA REPLACE;
RUN;

proc contents data = ct.fmy_decile;
run;

libname ct "&folder.";

%let meshclass = mesh_class3;

%let input = top50_drug_trials_addmkt;

%let output_long = myp_long; 
%let output_wide = my_wide; 
*market-year level data, var: p1-4 #ct, #results;


data raw;
	set ct.&input;
	if missing(&meshclass) = 0;

	if 2007 <= rgst_yr <= 2017;
	if 2007 <= start_yr <= 2017;
run;

%let max_rgst_date = '31Dec17'd;
%let min_rgst_date = '01Sep07'd;

data raw2;
	set raw;
	if find(NCT_Number, 'NCT')>0;
	if with_results=1 then NCT_withresult = NCT_Number;
	if &min_rgst_date <= Start_dt <= &max_rgst_date;
run;

proc contents data=raw2 varnum; 
run;

proc sort data=myp2  nodupkey;
	by &meshclass rgst_yr phase;
run;
*no dup;

data ct.&output_long;
	set myp2;
run; 
*mkt-year-phase level data;

/**************** transpose (reshape) *********************/

proc transpose data=myp2 out=wide1 prefix=n_ct_myp;
   by &meshclass rgst_yr;
   id phase;
   var n_ct_myp;
run;

proc transpose data=myp2 out=wide2 prefix=n_rs_myp;
   by &meshclass rgst_yr;
   id phase;
   var n_rs_myp;
run;

data mkt;
    merge  wide1(drop=_name_) wide2(drop=_name_);
    by &meshclass rgst_yr;
run;

data ct.&output_wide;
	set mkt;
run; 
*mkt-year level data. used in the next part;

libname ct "&folder.";

%let meshclass = mesh_class3;

%let input_firmmktyear = fmy_decile;
%let input_mktyear = my_wide;

%let output = fmy_own123;
*firm-mkt-year data with both own and peers' trials info; 



/********************  firm-market-year level  **************************/

proc contents data=raw2;
run;

*fmyp level;
proc sql;
  create table temp
  as select *, count(distinct(NCT_Number)) as n_ct_fmyp, count(distinct(NCT_withresult)) as n_rs_fmyp
  from raw2
  group by firm, &meshclass, rgst_yr, phase;

*merge myp2 back to set up a framework for firm-mkt-yr-phase;

PROC SQL;
	create table fmyp0 as
	select * 
	from myp0 a left join fy b
	on (a.rgst_yr = b.rgst_yr);
quit;

PROC SQL;
	create table fmyp2 as
	select * 
	from fmyp0 a left join fmyp b
	on (a.firm=b.firm) and (a.&meshclass=b.&meshclass) 
and (a.phase = b.phase) and (a.rgst_yr = b.rgst_yr);
quit;

proc expand data=temp2 out=temp3 method = none; 
  by firm &meshclass;
  id rgst_yr; 

  /*** own ***/

  *current year;
  convert n_ct_fmyp1 = own1  ; 
  convert n_ct_fmyp2 = own2   ; 
  convert n_ct_fmyp3 = own3   ; 

  *lag 1;
  convert n_ct_fmyp1 = own1_lag1   / transformout=(lag 1); 
  convert n_ct_fmyp2 = own2_lag1   / transformout=(lag 1); 
  convert n_ct_fmyp3 = own3_lag1   / transformout=(lag 1); 

  *lag 2;
  convert n_ct_fmyp1 = own1_lag2   / transformout=(lag 2); 
  convert n_ct_fmyp2 = own2_lag2   / transformout=(lag 2); 
  convert n_ct_fmyp3 = own3_lag2   / transformout=(lag 2); 

  *lead 1-3 (only phase 2);
  convert n_ct_fmyp2 = own2_lead1   / transformout=(lead 1); 
  convert n_ct_fmyp2 = own2_lead2   / transformout=(lead 2); 
  convert n_ct_fmyp2 = own2_lead3   / transformout=(lead 3); 

  /*** market wide ***/

  *n_ct;
  convert n_ct_myp1 = mkt1  ; 
  convert n_ct_myp2 = mkt2   ; 
  convert n_ct_myp3 = mkt3   ; 

  convert n_ct_myp1 = mkt1_lag1   / transformout=(lag 1); 
  convert n_ct_myp2 = mkt2_lag1   / transformout=(lag 1); 
  convert n_ct_myp3 = mkt3_lag1   / transformout=(lag 1); 

  convert n_ct_myp1 = mkt1_lag2   / transformout=(lag 2); 
  convert n_ct_myp2 = mkt2_lag2   / transformout=(lag 2); 
  convert n_ct_myp3 = mkt3_lag2   / transformout=(lag 2); 

run;

data ct.&output;
	set temp3;
run;

libname ct "&folder.";

%let input_decile = fmy_decile;
*decile rankings based on movsum 3 of number of phase 3 trials initiated;

%let input_fmy = fmy_own123; 
*gen by previous code;

%let output = fmy_forstata;
*use this output to run reg in stata;


data raw;
	set ct.&input_decile.;
	rgst_yr = year;
run;

/*****************************************************/
/*** LAST STEP --- load #p1, p2 by firm-mkt-year,
sum if strong/weak ***/
/*****************************************************/

data own;
	set ct.&input_fmy.;
	own1_lag12 = own1_lag1 + own1_lag2;
	own2_lag12 = own2_lag1 + own2_lag2;

proc means n mean std p25 p50 p75 maxdec= 2;
run;

data ct.&output;
	set rv_stwkmid;
run;


PROC EXPORT DATA=rv_stwkmid
            OUTFILE="&folder.\&output..dta"
            DBMS=STATA REPLACE;
RUN;

PROC EXPORT DATA=temp2
            OUTFILE="&folder.\&output..dta"
            DBMS=STATA REPLACE;
RUN;

PROC EXPORT DATA=rv_stwkmid
            OUTFILE="&folder.\&output..dta"
            DBMS=STATA REPLACE;
RUN;

edits.after:
run;
proc contents data=final3 varnum;
run;
